<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Achievement;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;class AchievementController extends Controller{public function index(){return view('admin.achievements.index',['items'=>Achievement::latest('event_date')->paginate(30)]);}public function create(){return view('admin.achievements.form',['item'=>new Achievement]);}public function store(Request $r){Achievement::create($this->data($r));return redirect()->route('admin.achievements.index')->with('ok','Достижение добавлено');}public function edit(Achievement $achievement){return view('admin.achievements.form',['item'=>$achievement]);}public function update(Request $r,Achievement $achievement){$old=$achievement->image;$d=$this->data($r);$achievement->update($d);if(isset($d['image'])&&$old&&$old!==$d['image'])Storage::disk('public')->delete($old);return redirect()->route('admin.achievements.index')->with('ok','Сохранено');}public function destroy(Achievement $achievement){if($achievement->image)Storage::disk('public')->delete($achievement->image);$achievement->delete();return back()->with('ok','Достижение удалено');}private function data(Request $r){$d=$r->validate(['title'=>'required|max:255','person'=>'nullable|max:255','kind'=>'required|in:student,teacher,collective','competition'=>'nullable|max:255','result'=>'nullable|max:255','event_date'=>'nullable|date','description'=>'nullable','image'=>'nullable|image|max:10240']);if($r->hasFile('image'))$d['image']=$r->file('image')->store('achievements','public');$d['is_published']=$r->boolean('is_published');return $d;}}